mapper.select:
select max(sort_no)
from play_queue_item
where queue_id = #{queueId}

mapper.update:
update play_queue_item
set sort_no = sort_no + 1
where queue_id = #{queueId}
  and sort_no >= #{sortNo}

update play_queue_item
set sort_no = sort_no - 1
where queue_id = #{queueId}
  and sort_no > #{sortNo}
